data=[]
for slug,i,title,cat,desc,dur,anchor in projects:
 data.append(dict(slug=slug,image=f'/assets/work-{i}.webp',title=title,category=cat,description=desc,duration=dur,watch=ORIGINAL+('#'+anchor if anchor else '/ai' if cat=='AI & animation' else '/3d')))
